var panels = Array.prototype.slice.call(root.querySelectorAll('.scn-panel-deck-panel'));
var dots = Array.prototype.slice.call(root.querySelectorAll('.scn-panel-deck-dot'));
var now = root.querySelector('.scn-panel-deck-now');
var label = root.querySelector('.scn-panel-deck-label');
var next = root.querySelector('.scn-panel-deck-next');
if (!scroller || !panels.length) return;
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var active = -1;
function setActive(i) {
  if (i < 0 || i >= panels.length || i === active) return;
  active = i;
  dots.forEach(function (d, n) {
    if (n === i) { d.setAttribute('aria-current', 'true'); } else { d.removeAttribute('aria-current'); }
  });
  if (now) now.textContent = String(i + 1);
  var t = panels[i].querySelector('.scn-panel-deck-title');
  if (label && t) label.textContent = t.textContent;
  if (next) next.disabled = i >= panels.length - 1;
}
function goTo(i) {
  i = Math.max(0, Math.min(panels.length - 1, i));
  scroller.scrollTo({ top: panels[i].offsetTop, behavior: reduce ? 'auto' : 'smooth' });
}
var io = new IntersectionObserver(function (entries) {
  var best = null;
  entries.forEach(function (e) {
    if (e.isIntersecting && (!best || e.intersectionRatio > best.intersectionRatio)) best = e;
