var track = root.querySelector('.scn-cover-carousel-track');
var cards = Array.prototype.slice.call(root.querySelectorAll('.scn-cover-carousel-card'));
var btns = Array.prototype.slice.call(root.querySelectorAll('.scn-cover-carousel-btn'));
var cur = root.querySelector('.scn-cover-carousel-cur');
var num = root.querySelector('.scn-cover-carousel-n');
if (!track || !cards.length) return;
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var pitch = 136;
var active = -1;
function pad(n) { return (n < 10 ? '0' : '') + n; }
function centreOf(el) { return el.offsetLeft - track.offsetLeft + el.offsetWidth / 2; }
function update() {
  var mid = track.scrollLeft + track.clientWidth / 2;
  var best = 0, bestD = Infinity;
  cards.forEach(function (c, i) {
    var d = centreOf(c) - mid;
    var a = Math.abs(d);
    if (a < bestD) { bestD = a; best = i; }
    if (!reduce) {
      var k = Math.min(1, a / pitch);
      c.style.transform = 'scale(' + (1 - 0.16 * k).toFixed(3) + ')';
      c.style.opacity = (1 - 0.55 * k).toFixed(3);
    }
  });
  if (best !== active) {
    active = best;
    cards.forEach(function (c, i) { c.classList.toggle('scn-cover-carousel-on', i === best); });
    var nm = cards[best].querySelector('.scn-cover-carousel-name');
    if (cur && nm) cur.textContent = nm.textContent;
    if (num) num.textContent = pad(best + 1);
  }
  btns.forEach(function (b) {
    b.disabled = b.getAttribute('data-dir') === '1' ? best >= cards.length - 1 : best <= 0;
  });
}
function centre(i) {
  i = Math.max(0, Math.min(cards.length - 1, i));
  track.scrollTo({ left: centreOf(cards[i]) - track.clientWidth / 2, behavior: reduce ? 'auto' : 'smooth' });
}
cards.forEach(function (c, i) { c.addEventListener('click', function () { centre(i); }); });
btns.forEach(function (b) {
  b.addEventListener('click', function () { centre(active + (b.getAttribute('data-dir') === '1' ? 1 : -1)); });
});
track.addEventListener('scroll', update, { passive: true });
track.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowRight') { e.preventDefault(); centre(active + 1); }
  else if (e.key === 'ArrowLeft') { e.preventDefault(); centre(active - 1); }
});
update();

