var scroller = root.querySelector('.scn-frame-gallery-scroll');
var slides = Array.prototype.slice.call(root.querySelectorAll('.scn-frame-gallery-slide'));
var bars = Array.prototype.slice.call(root.querySelectorAll('.scn-frame-gallery-bar'));
var cur = root.querySelector('.scn-frame-gallery-cur');
if (!scroller || !slides.length) return;
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var active = -1;
function update() {
  var w = scroller.clientWidth || 1;
  var pos = scroller.scrollLeft / w;
  slides.forEach(function (s, i) {
    var art = s.querySelector('.scn-frame-gallery-art');
    if (art && !reduce) art.style.transform = 'translateX(' + ((i - pos) * 26).toFixed(2) + 'px)';
  });
  var i = Math.round(pos);
  if (i !== active) {
    active = i;
    bars.forEach(function (b, n) { b.classList.toggle('scn-frame-gallery-done', n <= i); });
    if (cur) cur.textContent = String(i + 1);
  }
}
bars.forEach(function (b, i) {
  b.addEventListener('click', function () {
    scroller.scrollTo({ left: i * scroller.clientWidth, behavior: reduce ? 'auto' : 'smooth' });
  });
});
scroller.addEventListener('scroll', update, { passive: true });
update();

