    ink.style.transform = 'translateX(' + (p * (bar.clientWidth - w)) + 'px)';
  }
  var i = Math.round(p * (tabs.length - 1));
  if (i !== active) {
    active = i;
    tabs.forEach(function (t, n) {
      t.setAttribute('aria-selected', n === i ? 'true' : 'false');
      t.tabIndex = n === i ? 0 : -1;
    });
  }
}
function goTo(i, focus) {
  i = Math.max(0, Math.min(tabs.length - 1, i));
  panes.scrollTo({ left: i * panes.clientWidth, behavior: reduce ? 'auto' : 'smooth' });
  if (focus) tabs[i].focus();
}
tabs.forEach(function (t, i) {
  t.addEventListener('click', function () { goTo(i, false); });
  t.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowRight') { e.preventDefault(); goTo(i + 1, true); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); goTo(i - 1, true); }
    else if (e.key === 'Home') { e.preventDefault(); goTo(0, true); }
    else if (e.key === 'End') { e.preventDefault(); goTo(tabs.length - 1, true); }
  });
});
panes.addEventListener('scroll', place, { passive: true });
place();

css:
.scn-value-wheel{--scn-vw-ink:#f2f3f7;--scn-vw-dim:#767e8f;--scn-vw-acc:#63d2ff;box-sizing:border-box;width:100%;max-width:320px;padding:12px;border-radius:18px;background:linear-gradient(180deg,#14161c,#0a0b0e);border:1px solid rgba(255,255,255,.09);color:var(--scn-vw-ink);font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
.scn-value-wheel-head{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:6px;}
.scn-value-wheel-eyebrow{font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--scn-vw-dim);}
.scn-value-wheel-out{display:inline-flex;align-items:baseline;gap:4px;font-variant-numeric:tabular-nums;}
.scn-value-wheel-time{font:600 16px/1 ui-monospace,Menlo,monospace;color:var(--scn-vw-acc);letter-spacing:.02em;}
.scn-value-wheel-mer{font-style:normal;font-size:10px;color:var(--scn-vw-dim);letter-spacing:.1em;}
.scn-value-wheel-decks{position:relative;display:flex;gap:6px;border-radius:12px;background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.05);padding:0 6px;}
.scn-value-wheel-band{position:absolute;left:6px;right:6px;top:50%;height:42px;transform:translateY(-50%);border-radius:9px;background:rgba(99,210,255,.08);border-top:1px solid rgba(99,210,255,.35);border-bottom:1px solid rgba(99,210,255,.35);pointer-events:none;}
.scn-value-wheel-col{flex:1;height:210px;overflow-y:auto;overscroll-behavior:contain;scroll-snap-type:y mandatory;scrollbar-width:none;position:relative;border-radius:9px;}
.scn-value-wheel-col::-webkit-scrollbar{width:0;height:0;}
.scn-value-wheel-col:focus-visible{outline:2px solid var(--scn-vw-acc);outline-offset:-2px;}
.scn-value-wheel-mercol{flex:0 0 62px;}
.scn-value-wheel-list{padding:84px 0;perspective:520px;}
.scn-value-wheel-opt{height:42px;display:flex;align-items:center;justify-content:center;scroll-snap-align:center;font:500 19px/1 ui-monospace,Menlo,monospace;font-variant-numeric:tabular-nums;color:var(--scn-vw-ink);opacity:.35;backface-visibility:hidden;transition:color .2s ease;}
.scn-value-wheel-mercol .scn-value-wheel-opt{font-size:14px;letter-spacing:.08em;}
.scn-value-wheel-col:hover .scn-value-wheel-opt{color:#fff;}
.scn-value-wheel-sel{color:var(--scn-vw-acc);font-weight:600;}
.scn-value-wheel-col:hover .scn-value-wheel-sel{color:var(--scn-vw-acc);}
.scn-value-wheel-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:11px;}
.scn-value-wheel-note{font-size:10.5px;color:var(--scn-vw-dim);}
.scn-value-wheel-set{font:600 10px/1 system-ui,-apple-system,sans-serif;letter-spacing:.09em;text-transform:uppercase;color:#08131a;background:var(--scn-vw-acc);border:0;padding:8px 13px;border-radius:999px;cursor:pointer;transition:background-color .18s ease,transform .12s ease;}
.scn-value-wheel-set:hover{background-color:#8adfff;}
.scn-value-wheel-set:active{transform:scale(.95);}
.scn-value-wheel-set:focus-visible{outline:2px solid var(--scn-vw-acc);outline-offset:3px;}
.scn-value-wheel-done{background-color:#5ee7a8;color:#07160f;}
@media (prefers-reduced-motion: reduce){
.scn-value-wheel-col{scroll-behavior:auto;}
.scn-value-wheel-opt{transition:none;transform:none;opacity:1;}
.scn-value-wheel-set{transition:none;}
}

js:
var cols = Array.prototype.slice.call(root.querySelectorAll('.scn-value-wheel-col'));
var out = root.querySelector('.scn-value-wheel-time');
var mer = root.querySelector('.scn-value-wheel-mer');
var setBtn = root.querySelector('.scn-value-wheel-set');
if (!cols.length) return;
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var H = 42;
var picked = { h: '7', m: '45', p: 'AM' };
function paint(col) {
  var opts = Array.prototype.slice.call(col.querySelectorAll('.scn-value-wheel-opt'));
  var mid = col.scrollTop + col.clientHeight / 2;
  var sel = 0, best = Infinity;
  opts.forEach(function (o, i) {
    var d = (o.offsetTop + H / 2 - mid) / H;
    var a = Math.abs(d);
    if (a < best) { best = a; sel = i; }
    if (!reduce) {
      o.style.transform = 'rotateX(' + (-d * 22).toFixed(2) + 'deg) scale(' + (1 - Math.min(0.26, a * 0.09)).toFixed(3) + ')';
      o.style.opacity = Math.max(0.14, 1 - a * 0.34).toFixed(3);
    }
  });
  opts.forEach(function (o, i) {
    o.classList.toggle('scn-value-wheel-sel', i === sel);
    o.setAttribute('aria-selected', i === sel ? 'true' : 'false');
  });
  picked[col.getAttribute('data-unit')] = opts[sel] ? opts[sel].textContent.trim() : '';
  if (out) out.textContent = (picked.h.length < 2 ? '0' + picked.h : picked.h) + ':' + picked.m;
  if (mer) mer.textContent = picked.p;
  return sel;
}
cols.forEach(function (col) {
  var start = { h: 6, m: 9, p: 0 }[col.getAttribute('data-unit')] || 0;
  col.scrollTop = start * H;
  col.addEventListener('scroll', function () { paint(col); }, { passive: true });
  col.addEventListener('keydown', function (e) {
    if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
    e.preventDefault();
    var i = paint(col) + (e.key === 'ArrowDown' ? 1 : -1);
    var n = col.querySelectorAll('.scn-value-wheel-opt').length;
    i = Math.max(0, Math.min(n - 1, i));
    col.scrollTo({ top: i * H, behavior: reduce ? 'auto' : 'smooth' });
  });
  paint(col);
});
if (setBtn) {
  setBtn.addEventListener('click', function () {
    setBtn.textContent = 'Alarm set';
    setBtn.classList.add('scn-value-wheel-done');
    setTimeout(function () {
      if (!root.isConnected) return;
      setBtn.textContent = 'Set alarm';
      setBtn.classList.remove('scn-value-wheel-done');
    }, 1600);
  });
}
